import os
import binascii


def import_settings_from_environment_variables(config):
    """Import settings from environment variables into config."""
    # Map environment variables to config keys
    env_mapping = {
        'SYNCSERVER_SECRET': 'secret',
        'SYNCSERVER_SQLALCHEMY_URL': 'sqlalchemy.url',
        'SYNCSERVER_PUBLIC_URL': 'public_url',
        'SYNCSERVER_DEBUG': 'debug',
        'SYNCSERVER_ECHO': 'echo',
        'SYNCSERVER_POOL_SIZE': 'pool_size',
        'SYNCSERVER_POOL_TIMEOUT': 'pool_timeout',
        'SYNCSERVER_POOL_RECYCLE': 'pool_recycle',
        'SYNCSERVER_FORCE_SSL': 'force_ssl',
        'SYNCSERVER_HAWK_ID': 'hawk_id',
        'SYNCSERVER_HAWK_SECRET': 'hawk_secret',
    }
    for env_key, config_key in env_mapping.items():
        value = os.environ.get(env_key)
        if value is not None:
            if config_key.endswith('_url') or config_key == 'secret':
                config[config_key] = value
            elif config_key in ('debug', 'echo', 'force_ssl'):
                config[config_key] = str_to_bool(value)
            elif config_key in ('pool_size', 'pool_timeout', 'pool_recycle'):
                config[config_key] = int(value)
            else:
                config[config_key] = value
    return config


def str_to_bool(value):
    """Convert string to boolean."""
    if isinstance(value, bool):
        return value
    return value.lower() in ('true', '1', 'yes')


def generate_random_hex_key(num_bytes=32):
    """Generate a random hex key."""
    return binascii.hexlify(os.urandom(num_bytes)).decode('ascii')
